pub fn raw_find(buf: &[u8], n: usize, s: &[u8], from: usize) -> usize {
    let mut i: usize = from;
    while ((i + s.len()) <= n) {
        if raw_at(buf, i, s) {
            return i;
        }
        i = (i + 1);
    }
    return RAW_NONE;
}

pub fn raw_nibble(c: u8) -> u8 {
    if (c >= 97) {
        return (c - 87);
    }
    if (c >= 65) {
        return (c - 55);
    }
    return (c - 48);
}

pub fn raw_at_hex(out: &[u8], at: usize, hex: &[u8]) -> bool {
    if ((at + (hex.len() / 2)) > out.len()) {
        return false;
    }
    let mut i: usize = 0;
    while (i < (hex.len() / 2)) {
        if (out[((at + i)) as usize] != ((raw_nibble(hex[((2 * i)) as usize]) * 16) + raw_nibble(hex[(((2 * i) + 1)) as usize]))) {
            return false;
        }
        i = (i + 1);
    }
    return true;
}

pub fn raw_put_hex(out: &mut [u8], w: usize, hex: &[u8]) -> usize {
    let mut p: usize = w;
    let mut i: usize = 0;
    while (i < (hex.len() / 2)) {
        p = raw_put(out, p, ((raw_nibble(hex[((2 * i)) as usize]) * 16) + raw_nibble(hex[(((2 * i) + 1)) as usize])));
        i = (i + 1);
    }
    return p;
}

pub const RLC_VARS: &'static str = "time\ttime\nv(in)\tvoltage\nv(1)\tvoltage\nv(2)\tvoltage\ni(l1)\tcurrent\n";

pub const RLC_NVARS: usize = 5;

pub const RLC_PTS: usize = 201;

pub const RLC_VALS: usize = 1005;

pub const RLC_TITLE: &'static str = "m1 series rlc, backward euler on a fixed 5 ns grid";

pub fn raw_cell_trace(d: impl AsRef<[u32]>, nv: impl AsRef<[u32]>, vals: &mut [f64]) -> u64 {
    let d: &[u32] = d.as_ref();
    let nv: &[u32] = nv.as_ref();
    let mut x: [u32; 3] = [0; 3];
    let mut s: u64 = 0;
    let mut j: usize = 0;
    while (j < RLC_NVARS) {
        vals[(j) as usize] = 0.0;
        j = (j + 1);
    }
    let mut k: u32 = 0;
    while (k < STEPS) {
        let u: u32 = vin_at(k);
        let y0: u32 = step_row(0, RLC_N, d, nv, &(x), u);
        let y1: u32 = step_row(1, RLC_N, d, nv, &(x), u);
        let y2: u32 = step_row(2, RLC_N, d, nv, &(x), u);
        x[0] = y0;
        x[1] = y1;
        x[2] = y2;
        s = fold(s, y0);
        s = fold(s, y1);
        s = fold(s, y2);
        let row: usize = (((k + 1) as usize) * RLC_NVARS);
        vals[(row) as usize] = (((k + 1) as f64) * RLC_DT);
        vals[((row + 1)) as usize] = sm_f64(u);
        vals[((row + 2)) as usize] = sm_f64(y0);
        vals[((row + 3)) as usize] = sm_f64(y1);
        vals[((row + 4)) as usize] = (sm_f64(y2) / RLC_ZS);
        k = (k + 1);
    }
    return s;
}

pub fn raw_rlc_trace(vals: &mut [f64]) -> u64 {
    return raw_cell_trace(&(RLC_D), &(RLC_NV), vals);
}

pub fn raw_rlc_file(out: &mut [u8], date: &[u8], binary: bool, vals: &mut [f64], a: &mut [u64], d: &mut [u8]) -> usize {
    let s: u64 = raw_rlc_trace(vals);
    if (s != RLC_EXP_S) {
        return 0;
    }
    return raw_write(out, RLC_TITLE.as_bytes(), date, b"", b"Transient Analysis", RLC_VARS.as_bytes(), vals, binary, a, d);
}

pub const CHARGE_STEPS: u32 = 100;

pub const HALF_LSB: u64 = 8388608;

pub const MAG: u32 = 0x7FFFFFFF;

pub const NEG: u32 = 0x80000000;

pub const ONE: u32 = 16777216;

pub const RLC_D: [u32; 9] = [(NEG | 16777216), 797017, (NEG | 15940348), 0, (NEG | 39851), 797017, 0, (NEG | 797017), (NEG | 836868)];

pub const RLC_DT: f64 = 5.0e-9;

pub const RLC_EXP_S: u64 = 0x84BE2C7F9115D08A;

pub const RLC_N: usize = 3;

pub const RLC_NV: [u32; 3] = [15980199, 39851, 797017];

pub const RLC_ZS: f64 = 100.0;

pub const SCALE: f64 = 16777216.0;

pub const STEPS: u32 = 200;

pub fn add_sm(x: u32, dl: u32) -> u32 {
    let mx: u32 = (x & MAG);
    let md: u32 = (dl & MAG);
    if !(opposite(x, dl)) {
        return pack((mx + md), is_neg(x));
    }
    if (mx >= md) {
        return pack((mx - md), is_neg(x));
    }
    return pack((md - mx), is_neg(dl));
}

pub fn delta_of(pos: u64, neg: u64) -> u32 {
    if (pos >= neg) {
        return pack(round_back((pos - neg)), false);
    }
    return pack(round_back((neg - pos)), true);
}

pub fn fold(sum: u64, x: u32) -> u64 {
    return (((sum << 1) | (sum >> 63)) ^ (x as u64));
}

pub fn is_neg(p: u32) -> bool {
    return ((p & NEG) != 0);
}

pub fn neg_after(neg: u64, c: u32, x: u32) -> u64 {
    if opposite(c, x) {
        return (neg + prod(c, x));
    }
    return neg;
}

pub fn next_x(x: u32, pos: u64, neg: u64) -> u32 {
    return add_sm(x, delta_of(pos, neg));
}

pub fn opposite(c: u32, x: u32) -> bool {
    return (((c ^ x) & NEG) != 0);
}

pub fn pack(m: u32, neg: bool) -> u32 {
    if (m == 0) {
        return 0;
    }
    if neg {
        return (m | NEG);
    }
    return m;
}

pub fn pos_after(pos: u64, c: u32, x: u32) -> u64 {
    if opposite(c, x) {
        return pos;
    }
    return (pos + prod(c, x));
}

pub fn prod(c: u32, x: u32) -> u64 {
    return (((c & MAG) as u64) * ((x & MAG) as u64));
}

pub fn round_back(t: u64) -> u32 {
    return (((t + HALF_LSB) >> 24) as u32);
}

pub fn sm_f64(p: u32) -> f64 {
    let v: f64 = (((p & MAG) as f64) / SCALE);
    if is_neg(p) {
        return (0.0 - v);
    }
    return v;
}

pub fn step_row(i: usize, n: usize, d: impl AsRef<[u32]>, nv: impl AsRef<[u32]>, x: impl AsRef<[u32]>, u: u32) -> u32 {
    let d: &[u32] = d.as_ref();
    let nv: &[u32] = nv.as_ref();
    let x: &[u32] = x.as_ref();
    let mut pos: u64 = 0;
    let mut neg: u64 = 0;
    let mut j: usize = 0;
    while (j < n) {
        pos = pos_after(pos, d[(((i * n) + j)) as usize], x[(j) as usize]);
        neg = neg_after(neg, d[(((i * n) + j)) as usize], x[(j) as usize]);
        j = (j + 1);
    }
    pos = pos_after(pos, nv[(i) as usize], u);
    neg = neg_after(neg, nv[(i) as usize], u);
    return next_x(x[(i) as usize], pos, neg);
}

pub fn vin_at(n: u32) -> u32 {
    if (n < CHARGE_STEPS) {
        return ONE;
    }
    return 0;
}

